// SPDX-License-Identifier: AGPL-3.0-only
// The member register (P1.2): pages and facet counts for the club's
// administrators (full) and board (limited), and exports of the register as
// CSV, generated by the worker (members:export) and downloadable by the
// requester for 24 hours. Protected members are left out by the database
// unless the context is viewerPrivileged (set by the controller).

import { audit, type Database, outbox, type TenantContext } from "@clubadmin/db";
import type { ObjectStorage } from "@clubadmin/server-kit/object-storage";
import {
  type CreateMemberExportInput,
  CreateMemberExportSchema,
  type RegisterFilter,
  type RegisterSort,
} from "@clubadmin/shared";

import { DomainError } from "../../platform/domain/domain-error.ts";
import { actorPersonId, parseInput } from "../../platform/domain/run.ts";
import * as repo from "./members.repository.ts";

export type RegisterRow = repo.RegisterRow;
export type MemberExport = repo.MemberExportRow;

export interface MembersOptions {
  exportsPerPersonPerDay: number;
  exportsPerClubPerDay: number;
}

/** Pre-signed download links are valid this long. */
const DOWNLOAD_SECONDS = 5 * 60;

export class MembersService {
  private readonly db: Database;
  private readonly storage: ObjectStorage | null;
  private readonly options: MembersOptions;

  constructor(db: Database, storage: ObjectStorage | null, options: MembersOptions) {
    this.db = db;
    this.storage = storage;
    this.options = options;
  }

  registerPage(
    context: TenantContext,
    input: {
      filter: RegisterFilter;
      sort: RegisterSort;
      order: "asc" | "desc";
      cursor?: string | undefined;
      limit: number;
    },
  ): Promise<{ items: RegisterRow[]; nextCursor: string | null; totalCount: number }> {
    return this.db.withTenant(context, async (tx) => {
      const result = await repo.registerPage(tx, context.clubId, {
        filter: input.filter,
        sort: input.sort,
        order: input.order,
        cursor: input.cursor ?? null,
        limit: input.limit + 1,
        countHidden: input.filter.q === undefined,
      });
      if (!result.cursorFound) throw new DomainError("invalid_cursor");
      const items = result.items.slice(0, input.limit);
      return {
        items,
        nextCursor: result.items.length > input.limit ? items.at(-1)!.personId : null,
        totalCount: result.totalCount,
      };
    });
  }

  facets(context: TenantContext): Promise<repo.FacetRows> {
    return this.db.withTenant(context, (tx) => repo.registerFacets(tx, context.clubId));
  }

  /**
   * Queues an export (the insert trigger enqueues the worker job), records
   * the audit event and tells every club manager (members.exported).
   */
  requestExport(context: TenantContext, input: CreateMemberExportInput): Promise<MemberExport> {
    return this.db.withTenant(context, async (tx) => {
      const data = parseInput(CreateMemberExportSchema, input);
      const personId = actorPersonId(context);
      if (!this.storage) throw new DomainError("export_storage_unavailable");
      const recent = await repo.recentExportCounts(tx, context.clubId, personId);
      if (
        recent.byPerson >= this.options.exportsPerPersonPerDay ||
        recent.byClub >= this.options.exportsPerClubPerDay
      ) {
        throw new DomainError("export_limit_reached");
      }
      const row = await repo.insertExport(tx, {
        clubId: context.clubId,
        requestedByPersonId: personId,
        filter: data.filter,
        columns: data.columns,
        includeProtected: data.includeProtected,
      });
      // Which columns and whether protected members are in it; never values.
      await audit.record(tx, {
        action: "members.exported",
        resourceType: "member_export",
        resourceId: row.id,
        changedFields: [...data.columns, ...(data.includeProtected ? ["include_protected"] : [])],
      });
      await outbox.publish(tx, "members.exported", { exportId: row.id, clubId: context.clubId });
      return row;
    });
  }

  listExports(
    context: TenantContext,
    page: { cursor?: string | undefined; limit: number },
  ): Promise<{ items: MemberExport[]; nextCursor: string | null }> {
    return this.db.withTenant(context, async (tx) => {
      const rows = await repo.listExports(tx, context.clubId, {
        cursor: page.cursor ?? null,
        limit: page.limit + 1,
      });
      const items = rows.slice(0, page.limit);
      return {
        items,
        nextCursor: rows.length > page.limit ? items.at(-1)!.id : null,
      };
    });
  }

  /** A short-lived link to the file, for the requester only, while it is ready. */
  download(context: TenantContext, exportId: string): Promise<{ url: string; expiresAt: Date }> {
    return this.db.withTenant(context, async (tx) => {
      const row = await repo.findExport(tx, exportId);
      // Someone else's export is as good as missing.
      if (!row || row.requestedByPersonId !== actorPersonId(context)) {
        throw new DomainError("not_found");
      }
      if (
        row.status !== "ready" ||
        !row.objectKey ||
        !row.expiresAt ||
        row.expiresAt <= new Date()
      ) {
        throw new DomainError("export_not_available");
      }
      if (!this.storage) throw new DomainError("export_storage_unavailable");
      await audit.record(tx, {
        action: "members.export.downloaded",
        resourceType: "member_export",
        resourceId: row.id,
      });
      const date = row.createdAt.toISOString().slice(0, 10);
      return {
        url: this.storage.presignDownload(row.objectKey, {
          expiresSeconds: DOWNLOAD_SECONDS,
          filename: `members-${date}.csv`,
        }),
        expiresAt: new Date(Date.now() + DOWNLOAD_SECONDS * 1000),
      };
    });
  }
}
